"""Cross-language checks against a fixture generated by analysis_bundle_export_test."""
import contextlib
import io
import json
from pathlib import Path
import shutil
import sys
import tempfile
import unittest

from tools.analysis_bundle.inspect_bundle import Bundle, main

FIXTURE = None


class InspectionTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name) / "bundle"
        shutil.copytree(FIXTURE, self.root)
        self.bundle = Bundle(self.root)

    def test_native_export_round_trip_and_foreign_triangle(self):
        face = self.bundle.surface(name="平面 406")
        self.assertEqual(list(self.bundle.point_indices(face)), [0, 1, 2])
        result = self.bundle.analyze(face)
        self.assertEqual(result["observations_read"], 3)
        self.assertEqual(result["centroid"], [1/3, 2/3, 0])
        self.assertEqual(result["measured_plane_residual"]["max"], 0)
        self.assertEqual(result["mesh"]["foreign_source_vertices"], 1)
        self.assertEqual(result["mesh"]["foreign_triangle_area"], 25)
        group = self.bundle.plane_group(face)
        self.assertEqual([row["id"] for row in group["members"]], [182, 418])
        self.assertTrue(group["domain_support_checks"][0]["rejected"])
        self.assertEqual(self.bundle.verify(True)["verification"], "all_assets")

    def test_metadata_commands_work_without_raw_files(self):
        for name in ("points.bin", "point-map.bin", "meshes.bin"):
            (self.root / name).unlink()
        for command in (["list"], ["show", "--id", "182", "--group"], ["verify"]):
            output = io.StringIO()
            with contextlib.redirect_stdout(output):
                self.assertEqual(main(["--bundle", str(self.root), *command]), 0)
            json.loads(output.getvalue())

    def test_point_mapping_does_not_read_coordinates(self):
        (self.root / "points.bin").unlink()
        self.assertEqual(list(self.bundle.point_indices(self.bundle.surface(surface_id=418))), [3])
        self.assertEqual(list(self.bundle.point_indices(self.bundle.surface(surface_id=0))), [5])

    def test_snapshot_identity_and_truncation(self):
        path = self.root / "points.bin"
        raw = bytearray(path.read_bytes())
        raw[24] ^= 1
        path.write_bytes(raw)
        with self.assertRaisesRegex(ValueError, "different snapshot"):
            list(self.bundle.points(self.bundle.surface(surface_id=182)))
        raw[24] ^= 1
        path.write_bytes(raw[:-1])
        with self.assertRaisesRegex(ValueError, "Truncated"):
            list(self.bundle.points(self.bundle.surface(surface_id=182)))

    def test_checksums_and_paths(self):
        face = self.bundle.surface(surface_id=182)
        (self.root / face["shared_plane"]["metadata"]).write_text("{}")
        with self.assertRaisesRegex(ValueError, "checksum"):
            self.bundle.plane_group(face)
        with self.assertRaisesRegex(ValueError, "escapes"):
            self.bundle._json("../outside.json")

    def test_explicit_raw_output_is_bounded(self):
        output = io.StringIO()
        with contextlib.redirect_stdout(output):
            main(["--bundle", str(self.root), "points", "--id", "182", "--limit", "1"])
        result = json.loads(output.getvalue())
        self.assertEqual(len(result["raw_points"]), 1)
        self.assertEqual(result["total_points"], 3)
        with contextlib.redirect_stderr(io.StringIO()), self.assertRaises(SystemExit):
            main(["--bundle", str(self.root), "points", "--id", "182", "--limit", "101"])

    def test_mapping_count_corruption(self):
        face = self.bundle.surface(surface_id=182)
        face["point_map"]["count"] += 1
        with self.assertRaisesRegex(ValueError, "Mapping count"):
            list(self.bundle.point_indices(face))

    def test_duplicate_names_require_id(self):
        rows = list(self.bundle.surfaces())
        rows[-1]["name"] = rows[-2]["name"]
        with self.assertRaisesRegex(ValueError, "Ambiguous"):
            self.bundle.surface(name=rows[-2]["name"])


if __name__ == "__main__":
    FIXTURE = Path(sys.argv.pop(1)).resolve()
    unittest.main()
